def choose(n, k):
	if 0 <= k <= n:
		ntok = 1
		ktok = 1
		for t in range(1, min(k, n - k) + 1):
			ntok *= n
			ktok *= t
			n -= 1
		return ntok // ktok
	else:
		return 0
T = 1
T = int(input().strip())
for _ in range(T):
	(n, k) = map(int, input().split())
	print(int(choose(n, k)))
